import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import pandas as pd

RC_PARAMS = {
    "font.size": 9,
    "axes.labelsize": 9,
    "axes.titlesize": 9,
    "xtick.labelsize": 8,
    "ytick.labelsize": 8,
    "legend.fontsize": 8,
    "axes.linewidth": 0.8,
    "xtick.major.width": 0.8,
    "ytick.major.width": 0.8,
}

FIGSIZE = (3.4, 2.6)
PALETTE = ["#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9", "#8C564B", "#000000"]
RECEDED_ALPHA = 0.4

DATA_PATH = "data/training.csv"
X_FIELD = "epoch"
Y_FIELD = "accuracy"
STEM = "03-single-run"
FORMATS = ["png", "svg", "pdf"]
DPI = 600


def load():
    return pd.read_csv(DATA_PATH)


def aggregate(df):
    keys = [X_FIELD]
    # sort=False keeps the file's category order instead of an alphabetical one.
    return df.groupby(keys, as_index=False, sort=False)[Y_FIELD].mean()


def draw(ax, df):
    df = aggregate(df)
    frame = df
    frame = frame.sort_values(X_FIELD)
    ax.plot(
        frame[X_FIELD],
        frame[Y_FIELD],
        color=PALETTE[0],
        linewidth=1.4,
        zorder=2,
        marker="o",
    )


def finish(fig, ax):
    ax.set_xlabel("Training epoch")
    ax.set_ylabel("Test accuracy (%)")
    ax.grid(False)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    fig.tight_layout()


def main():
    df = load()
    with plt.rc_context(RC_PARAMS):
        fig, ax = plt.subplots(figsize=FIGSIZE)
        draw(ax, df)
        finish(fig, ax)
        for fmt in FORMATS:
            path = f"{STEM}.{fmt}"
            kwargs = {"bbox_inches": "tight"}
            if fmt == "png":
                kwargs["dpi"] = DPI
            fig.savefig(path, **kwargs)
            print(f"wrote {path}")
    plt.close(fig)


if __name__ == "__main__":
    main()
